43	namespace {
44	const char *const kAttrAscGraph = "ascgraph";
45	constexpr int64_t kInvalidNodeId = -1;
46	constexpr size_t kMaxGraphNameLength = 60UL;  // 截断后的最大graph name长度
47	
48	// 截断 graph name，保留前 kMaxGraphNameLength 个字符
49	std::string TruncateGraphName(const std::string &name) {
50	  if (name.length() <= kMaxGraphNameLength) {
51	    return name;
52	  }
53	  return name.substr(0, kMaxGraphNameLength);
54	}
55	
56	// graph_name添加索引格式为: original_name_S{result_idx}G{group_idx}C{impl_idx}
57	std::string GenerateIndexedGraphName(const std::string &original_name, size_t result_idx, size_t group_idx,
58	                                     size_t impl_idx) {
59	  std::ostringstream oss;
60	  oss << original_name << "_S" << result_idx << "G" << group_idx << "C" << impl_idx;
61	  return oss.str();
62	}
63	
64	Status FinalizeIndexedGraphs(std::vector<ascir::ScheduledResult> &scheduled_results) {
65	  for (size_t result_idx = 0UL; result_idx < scheduled_results.size(); ++result_idx) {
66	    auto &scheduled_result = scheduled_results[result_idx];
67	    for (size_t group_idx = 0UL; group_idx < scheduled_result.schedule_groups.size(); ++group_idx) {
68	      auto &schedule_group = scheduled_result.schedule_groups[group_idx];
69	      for (size_t impl_idx = 0UL; impl_idx < schedule_group.impl_graphs.size(); ++impl_idx) {
70	        auto &impl_graph = schedule_group.impl_graphs[impl_idx];
71	        std::string old_name = impl_graph.GetName();
72	        std::string new_name = GenerateIndexedGraphName(old_name, result_idx, group_idx, impl_idx);
73	        // 修改 impl_graph 的 name
74	        auto compute_graph = af::AscGraphUtils::GetComputeGraph(impl_graph);
75	        GE_ASSERT_NOTNULL(compute_graph);
76	        compute_graph->SetName(new_name);
77	        GELOGD("Rename graph: [%s] -> [%s]", old_name.c_str(), new_name.c_str());
78	
79	        // 如果有 score func，直接在 map 中更新 key（只查找一次）
80	        auto node = schedule_group.graph_name_to_score_funcs.extract(old_name);
81	        if (!node.empty()) {
82	          node.key() = std::move(new_name);
83	          schedule_group.graph_name_to_score_funcs.insert(std::move(node));
84	          GELOGD("Update score func key: [%s] -> [%s]", old_name.c_str(), node.key().c_str());
85	        }
86	      }
87	    }
88	  }
89	  return af::SUCCESS;
90	}
91	
92	bool IsAxisContinuous(const af::AscGraph &graph, const int64_t pre_id_idx, const int64_t post_id_idx) {
93	  for (const auto &node : graph.GetAllNodes()) {
94	    if (ScheduleUtils::IsBuffer(node)) {
95	      continue;
96	    }
97	    auto pre_id = node->attr.sched.axis[pre_id_idx];
98	    auto post_id = node->attr.sched.axis[post_id_idx];
99	    for (auto &out_tensor : node->outputs()) {
100	      auto pre_iter = std::find(out_tensor->attr.axis.begin(), out_tensor->attr.axis.end(), pre_id);
101	      auto post_iter = std::find(out_tensor->attr.axis.begin(), out_tensor->attr.axis.end(), post_id);
102	      if ((pre_iter == out_tensor->attr.axis.end()) || (post_iter == out_tensor->attr.axis.end())) {
103	        return false;
104	      }
105	      auto pre_idx = std::distance(out_tensor->attr.axis.begin(), pre_iter);
106	      auto post_idx = std::distance(out_tensor->attr.axis.begin(), post_iter);
107	      auto post_stride = out_tensor->attr.strides[post_idx] * out_tensor->attr.repeats[post_idx];
108	      if ((pre_idx + 1 != post_idx) ||
109	          (af::SymbolicUtils::StaticCheckEq(out_tensor->attr.strides[pre_idx], post_stride) != af::TriBool::kTrue)) {
110	        return false;
111	      }
112	    }
113	  }
114	  return true;
115	}
116	
117	std::vector<std::vector<int64_t>> MergeContinuousPairs(const std::vector<std::pair<int64_t, int64_t>> &potential_axis) {
118	  std::vector<std::vector<int64_t>> continuous_ids;
119	  if (potential_axis.empty()) {
120	    return continuous_ids;
121	  }
122	
123	  std::vector<int64_t> current_chain;
124	  current_chain.push_back(potential_axis[0].first);
125	  current_chain.push_back(potential_axis[0].second);
126	
127	  for (size_t i = 1UL; i < potential_axis.size(); ++i) {
128	    const auto &cur_pair = potential_axis[i];
129	    if (current_chain.back() == cur_pair.first) {
130	      current_chain.push_back(cur_pair.second);
131	    } else {
132	      continuous_ids.push_back(current_chain);
133	      current_chain.clear();
134	      current_chain.push_back(cur_pair.first);
135	      current_chain.push_back(cur_pair.second);
136	    }
137	  }
138	  continuous_ids.push_back(current_chain);
139	
140	  return continuous_ids;
141	}
142	
143	std::unordered_set<size_t> IdentifyZeroStrideAxisIndices(const ascir::ImplGraph &owner_graph) {
144	  std::vector<bool> is_zero_stride_axis;
145	  bool include_reduce = false;
146	  for (const auto &node : owner_graph.GetAllNodes()) {
147	    GE_ASSERT_NOTNULL(node);
148	    if (!ScheduleUtils::IsBuffer(node) && is_zero_stride_axis.empty()) {
149	      is_zero_stride_axis.resize(node->attr.sched.axis.size(), true);
150	    }
151	    if (ScheduleUtils::IsReduce(node)) {
152	      include_reduce = true;
153	    }
154	  }
155	
156	  for (const auto &node : owner_graph.GetAllNodes()) {
157	    GE_ASSERT_NOTNULL(node);
158	    if (ScheduleUtils::IsBuffer(node)) {
159	      continue;
160	    }
161	
162	    // 当前节点包含_keep_first_axis属性且为true，或者图上包含reduce节点时，需要保留首轴
163	    bool keep_first_axis = false;
164	    (void)af::AttrUtils::GetBool(node->GetOpDesc(), "_keep_first_axis", keep_first_axis);
165	    keep_first_axis = keep_first_axis || include_reduce;
166	
167	    const auto &loop_axes = node->attr.sched.axis;
168	    for (size_t loop_idx = 0UL; loop_idx < loop_axes.size(); ++loop_idx) {
169	      bool has_non_zero_stride = false;
170	      for (const auto &output : node->outputs()) {
171	        auto iter = std::find(output->attr.axis.begin(), output->attr.axis.end(), loop_axes[loop_idx]);
172	        GE_ASSERT_TRUE(iter != output->attr.axis.end());
173	
174	        auto axis_index = static_cast<size_t>(std::distance(output->attr.axis.begin(), iter));
175	        GE_ASSERT_TRUE(axis_index < output->attr.strides.size(), "axis index [%zu] is out of range, max_size:[%zu].",
176	                       axis_index, output->attr.strides.size());
177	
178	        if (af::SymbolicUtils::StaticCheckEq(output->attr.strides[axis_index], af::sym::kSymbolZero) !=
179	                af::TriBool::kTrue ||
180	            (keep_first_axis && (axis_index == 0))) {
181	          has_non_zero_stride = true;
182	          break;
183	        }
184	      }
185	
186	      if (has_non_zero_stride) {
187	        is_zero_stride_axis[loop_idx] = false;
188	      }
189	    }
190	  }
191	
192	  std::unordered_set<size_t> zero_stride_axis_indices;
193	  for (size_t i = 0UL; i < is_zero_stride_axis.size(); ++i) {
194	    if (is_zero_stride_axis[i]) {
195	      zero_stride_axis_indices.emplace(i);
196	    }
197	  }
198	  // 全0场景,不需要删除
199	  if (zero_stride_axis_indices.size() == is_zero_stride_axis.size()) {
200	    return {};
201	  }
202	
203	  return zero_stride_axis_indices;
204	}
205	
206	Status GetDirectFatherNode(const af::AscGraph &impl_graph, std::map<int64_t, int64_t> &dir_father_nodes) {
207	  for (const auto &node : impl_graph.GetAllNodes()) {
208	    GE_CHECK_NOTNULL(node);
209	    GE_CHECK_NOTNULL(node->GetOpDesc());
210	    for (const auto &out_node : node->GetOutAllNodes()) {
211	      GE_CHECK_NOTNULL(out_node);
212	      GE_CHECK_NOTNULL(out_node->GetOpDesc());
213	      // 若输出节点为store或output，则认为其父节点即自己，否则所有节点的公共父节点都会搜索到store->output节点，保证并查集能够搜索到两个节点的公共计算节点。
214	      if (af::ops::IsOps<Store>(out_node) || af::ops::IsOps<Output>(out_node)) {
215	        dir_father_nodes.insert(std::make_pair(node->GetOpDesc()->GetId(), node->GetOpDesc()->GetId()));
216	        continue;
217	      }
218	      dir_father_nodes.insert(std::make_pair(node->GetOpDesc()->GetId(), out_node->GetOpDesc()->GetId()));
219	    }
220	  }
221	  return af::SUCCESS;
222	}
223	
224	int64_t FindRoot(std::map<int64_t, int64_t> &dir_father_nodes, const int64_t node_id) {
225	  if (node_id == dir_father_nodes[node_id]) {
226	    return node_id;
227	  }
228	  return dir_father_nodes[node_id] = FindRoot(dir_father_nodes, dir_father_nodes[node_id]);
229	}
230	
231	bool HasSameComputeNode(std::map<int64_t, int64_t> &dir_father_nodes, int64_t node0_id, int64_t node1_id) {
232	  node0_id = FindRoot(dir_father_nodes, node0_id);
233	  node1_id = FindRoot(dir_father_nodes, node1_id);
234	  return node0_id == node1_id;
235	}
236	
237	Status GetMapFromQueId2LoadId(const af::AscGraph &impl_graph,
238	                              std::map<int64_t, vector<int64_t>> &loads_with_same_queid) {
239	  for (const auto &node : impl_graph.GetAllNodes()) {
240	    GE_CHECK_NOTNULL(node);
241	    GE_CHECK_NOTNULL(node->GetOpDesc());
242	    if (!af::ops::IsOps<Load>(node)) {
243	      continue;
244	    }
245	    if (loads_with_same_queid.find(node->outputs[0].attr.que.id) != loads_with_same_queid.end()) {
246	      loads_with_same_queid[node->outputs[0].attr.que.id].emplace_back(node->GetOpDesc()->GetId());
247	      continue;
248	    }
249	    vector<int64_t> temp_load_ids = {node->GetOpDesc()->GetId()};
250	    loads_with_same_queid.insert(std::make_pair(node->outputs[0].attr.que.id, temp_load_ids));
251	  }
252	  return af::SUCCESS;
253	}
254	
255	Status SearchNodesNeedForward(const af::AscGraph &impl_graph, std::map<int64_t, int64_t> &need_forward_nodes_id,
256	                              int64_t &first_load_id) {
257	  std::map<int64_t, int64_t> dir_father_nodes;  // 以节点id形式存储所有节点的直接父节点
258	  GE_ASSERT_SUCCESS(GetDirectFatherNode(impl_graph, dir_father_nodes));
259	  constexpr size_t load_thresh = 2UL;    // 能够参与调序的load节点个数阈值
260	  size_t num_of_load_need_adjust = 0UL;  // 用于记录需要调序的load节点个数，判断是否达到阈值
261	  size_t index_data_and_load = 0UL;
262	  std::map<int64_t, vector<int64_t>> loads_with_same_queid;  // 获取TQue的共复用情况
263	  GE_ASSERT_SUCCESS(GetMapFromQueId2LoadId(impl_graph, loads_with_same_queid));
264	  for (const auto &node : impl_graph.GetAllNodes()) {
265	    GE_CHECK_NOTNULL(node);
266	    GE_CHECK_NOTNULL(node->GetOpDesc());
267	    if (num_of_load_need_adjust >= load_thresh) {
268	      GELOGD("The number of loads that need to be brought forward is %zu, which reaches threshold %zu.",
269	             num_of_load_need_adjust, load_thresh);
270	      break;
271	    }
272	    if (first_load_id == kInvalidNodeId && af::ops::IsOps<Load>(node)) {
273	      first_load_id = node->GetOpDesc()->GetId();
274	      num_of_load_need_adjust++;
275	      continue;
276	    }
277	    // 记录需要调序的input(data/workspace)和load节点：1. 非首load 2. 未被共复用 3. 和首load有公共计算节点 4.
278	    // 输出节点为非多输入节点
279	    if (first_load_id != kInvalidNodeId && af::ops::IsOps<Load>(node) && node->GetOpDesc()->GetId() > first_load_id &&
280	        loads_with_same_queid[node->outputs[0].attr.que.id].size() == 1UL &&
281	        HasSameComputeNode(dir_father_nodes, node->GetOpDesc()->GetId(), first_load_id)) {
282	      for (const auto &in_node : node->GetInAllNodes()) {
283	        GE_CHECK_NOTNULL(in_node);
284	        GE_CHECK_NOTNULL(in_node->GetOpDesc());
285	        if (ScheduleUtils::IsBuffer(std::dynamic_pointer_cast<af::AscNode>(in_node)) &&
286	            in_node->GetOpDesc()->GetId() > first_load_id) {
287	          GELOGD("Input node %s is after first load, needs to be advanced.", in_node->GetNamePtr());
288	          need_forward_nodes_id.insert(std::make_pair(in_node->GetOpDesc()->GetId(), index_data_and_load++));
289	        }
290	      }
291	      if (ScheduleUtils::IsOutNodeWithMultiInputs(node)) {
292	        continue;
293	      }
294	      GELOGD("Node %s needs to be advanced.", node->GetNamePtr());
295	      need_forward_nodes_id.insert(std::make_pair(node->GetOpDesc()->GetId(), index_data_and_load++));
296	      num_of_load_need_adjust++;
297	    }
298	  }
299	  return af::SUCCESS;
300	}
301	
302	Status DoSeqAdjustment(const af::AscGraph &impl_graph, const std::map<int64_t, int64_t> &need_forward_nodes_id,
303	                       const int64_t &first_load_id) {
304	  const size_t need_forward_nodes_num = need_forward_nodes_id.size();
305	  if (need_forward_nodes_num <= 0UL || first_load_id == kInvalidNodeId) {
306	    return af::SUCCESS;
307	  }
308	  int64_t start_index_other_nodes = first_load_id + static_cast<int64_t>(need_forward_nodes_num) + 1;
309	  for (const auto &node : impl_graph.GetAllNodes()) {
310	    GE_CHECK_NOTNULL(node);
311	    GE_CHECK_NOTNULL(node->GetOpDesc());
312	    if (node->GetOpDesc()->GetId() <= first_load_id) {
313	      continue;
314	    }
315	    if (node->GetOpDesc()->GetId() > need_forward_nodes_id.rbegin()->first) {
316	      GELOGD("No need to adjust node after node %" PRId64 ".", need_forward_nodes_id.rbegin()->first);
317	      break;
318	    }
319	    if (need_forward_nodes_id.find(node->GetOpDesc()->GetId()) != need_forward_nodes_id.end()) {
320	      GELOGD("Move node with id %" PRId64 " and name %s forward.", node->GetOpDesc()->GetId(), node->GetNamePtr());
321	      node->GetOpDesc()->SetId(first_load_id + need_forward_nodes_id.at(node->GetOpDesc()->GetId()) + 1);
322	      continue;
323	    }
324	    node->GetOpDesc()->SetId(start_index_other_nodes++);
325	  }
326	  return af::SUCCESS;
327	}
