421	bool IsRemovableDanglingNode(const af::NodePtr &node) {
422	  if (node == nullptr) {
423	    return false;
424	  }
425	  // 参照PassUtils::PruneGraph中的实现，保留输入输出节点
426	  if (IsOps<Data>(node) || IsOps<ScalarData>(node) || IsOps<Output>(node) || IsOps<Workspace>(node)) {
427	    return false;
428	  }
429	  return node->GetOutDataNodesSize() == 0U && node->GetOutControlNodesSize() == 0U;
430	}
