476	Status RemoveDanglingNodes(const af::ComputeGraphPtr &graph) {
477	  GE_ASSERT_NOTNULL(graph);
478	  size_t total_removed = 0UL;
479	  bool has_removed = false;
480	  do {
481	    has_removed = false;
482	    std::vector<af::NodePtr> nodes_to_remove;
483	    // 先收集再删除，避免遍历过程中修改图节点容器
484	    for (const auto &node : graph->GetDirectNode()) {
485	      GE_ASSERT_NOTNULL(node);
486	      if (IsRemovableDanglingNode(node)) {
487	        nodes_to_remove.push_back(node);
488	      }
489	    }
490	    for (const auto &node : nodes_to_remove) {
491	      GELOGW("Remove dangling node [%s], type [%s], graph [%s].", node->GetNamePtr(), node->GetTypePtr(),
492	             graph->GetName().c_str());
493	      GE_ASSERT_GRAPH_SUCCESS(graph->RemoveNode(node));
494	      ++total_removed;
495	      has_removed = true;
496	    }
497	    // 删除末端节点后，上游节点可能变成新的无消费者节点
498	  } while (has_removed);
499	  GELOGI("Remove dangling nodes end, graph [%s], removed node num [%zu].", graph->GetName().c_str(), total_removed);
500	  return af::SUCCESS;
501	}
