525	                                                std::vector<ascir::ScheduledResult> &scheduled_results_cur,
526	                                                size_t index, ScheduleTask &schedule_task) const {
527	  std::vector<ascir::ScheduledResult> scheduled_results_tmp;
528	  for (auto &schedule_output : schedule_outputs) {
529	    ScheduleGroup schedule_group = {{schedule_output.scheduled_graph}, {}};
530	    for (auto &d : scheduled_results_cur) {
531	      for (auto &existing_group : d.schedule_groups) {
532	        ScheduleGroup copied_group;
533	        copied_group.impl_graphs.reserve(existing_group.impl_graphs.size());
534	        for (const auto &impl_graph : existing_group.impl_graphs) {
535	          ascir::ImplGraph copied(impl_graph.GetName().c_str());
536	          GE_ASSERT_TRUE(copied.CopyFrom(impl_graph));
537	          copied_group.impl_graphs.push_back(std::move(copied));
538	        }
