555	Status Optimizer::Optimize(const af::ComputeGraphPtr &fused_graph,
556	                           ascir::FusedScheduledResult &fused_scheduled_result) {
557	  GELOGI("Fused graph optimize in, graph_name:[%s].", fused_graph->GetName().c_str());
558	  // RAII Guard，函数结束时自动清空 fused_graph_name
559	  ascir::utils::FusedGraphNameGuard guard(fused_graph->GetName());
560	  ascir::utils::DumpComputeGraph(fused_graph, "BaseFusedGraph");
561	  if (options_.graph_type == GraphType::kFusedAscBackend) {
562	    return OptimizeFusedAscBackend(fused_graph, fused_scheduled_result);
563	  }
564	  // deserialize ascgraph on ascgraph node
565	  std::map<af::Node *, af::AscGraph> asc_backend_to_ascgraph;
566	  SizeVarSet original_var_set;
567	  for (auto &node : fused_graph->GetDirectNodePtr()) {
568	    GE_ASSERT_NOTNULL(node);
569	    if (node->GetType() == kAscGraphNodeType) {
570	      const std::string *serialized_ascgraph = af::AttrUtils::GetStr(node->GetOpDescBarePtr(), kAttrAscGraph);
571	      GE_ASSERT_NOTNULL(serialized_ascgraph, "Failed to get serialized ascgraph attr from node:[%s].",
572	                        node->GetNamePtr());
573	      std::string graph_name = node->GetName() + "_ascgraph";
574	      af::AscGraph ascgraph(graph_name.c_str());
575	      GE_CHK_STATUS_RET(af::AscGraphUtils::DeserializeFromReadable(*serialized_ascgraph, ascgraph),
576	                        "DeserializeFromBinary failed, graph:[%s].", fused_graph->GetName().c_str());
577	      ascgraph.SetGraphType(af::AscGraphType::kImplGraph);
578	      GE_CHK_STATUS_RET(AscGraphInfoComplete::CompleteApiInfo(ascgraph), "CompleteApiInfo failed");
579	      AscGraphInfoComplete::AppendOriginalSizeVar(ascgraph, original_var_set);
580	      ascir::utils::DumpGraph(ascgraph, "AfterDeserialize");
581	      asc_backend_to_ascgraph.emplace(node, ascgraph);
582	    }
583	  }
584	  GE_ASSERT_TRUE(!asc_backend_to_ascgraph.empty(), "The fused graph [%s] is invalid, which has none AscBackend node.",
585	                 fused_graph->GetName().c_str());
586	
587	  // If there is more than one Ascend backend on the fused graph, it is necessary to determine whether partial sub -
588	  // graphs can be merged based on the supported scenarios. If there are still more than one Ascend nodes after the
589	  // merging, it should be converted into multiple schedule groups.
590	  af::AscGraph hint_graph(fused_graph->GetName().c_str());
591	  if (asc_backend_to_ascgraph.size() > 1UL) {
592	    GE_CHK_STATUS_RET(FusedGraphUnfolder::UnfoldFusedGraph(fused_graph, asc_backend_to_ascgraph, hint_graph),
593	                      "Failed to unfold graph[%s].", fused_graph->GetName().c_str());
594	  } else {
595	    hint_graph = asc_backend_to_ascgraph.begin()->second;
596	  }
597	
598	  auto owner_graph = af::AscGraphUtils::GetComputeGraph(hint_graph);
599	  GE_ASSERT_NOTNULL(owner_graph);
600	  owner_graph->SetName(ascgen_utils::GenValidName(fused_graph->GetName()));
601	  GE_ASSERT_SUCCESS(Optimize(hint_graph, fused_scheduled_result), "optimize failed, graph:[%s].",
602	                    hint_graph.GetName().c_str());
603	  // modify origin var and fused_graph
604	  fused_scheduled_result.fused_graph_name = fused_graph->GetName().c_str();
605	  fused_scheduled_result.origin_vars.assign(original_var_set.begin(), original_var_set.end());
606	  return af::SUCCESS;
607	}
