609	Status Optimizer::OptimizeFusedAscBackend(const af::ComputeGraphPtr &fused_graph,
610	                                          ascir::FusedScheduledResult &fused_scheduled_result) const {
611	  std::map<af::Node *, af::AscGraph> asc_backend_to_ascgraph;
612	  SizeVarSet original_var_set;
613	  for (auto &node : fused_graph->GetDirectNodePtr()) {
614	    GE_ASSERT_NOTNULL(node);
615	    if (node->GetType() == kAscBackendType) {
616	      const auto fuse_attr = node->GetOpDesc()->GetAttrsGroup<af::AutoFuseAttrs>();
617	      GE_ASSERT_NOTNULL(fuse_attr, "Node %s has no AutoFuseAttrs", node->GetName().c_str());
618	      auto fuse_asc_graph = fuse_attr->GetAscGraph();
619	      GE_ASSERT_NOTNULL(fuse_asc_graph, "Cannot get ascgraph from ascbc node:[%s].", node->GetNamePtr());
620	      ascir::utils::DumpGraph(*fuse_asc_graph, "AutoFuseBeforeRemoveDanglingNodes");
621	      GE_CHK_STATUS_RET(RemoveDanglingNodes(*fuse_asc_graph), "Remove dangling nodes failed, graph:[%s].",
622	                        fuse_asc_graph->GetName().c_str());
623	      ::ascir::utils::DumpGraph(*fuse_asc_graph, "AutoFuseBeforeOptimize");
624	      AscGraphInfoComplete::AppendOriginalSizeVar(*fuse_asc_graph, original_var_set);
625	      asc_backend_to_ascgraph.emplace(node, *fuse_asc_graph);
626	    }
627	  }
628	  GE_ASSERT_TRUE(!asc_backend_to_ascgraph.empty(), "The fused graph [%s] is invalid, which has none AscBackend node.",
629	                 fused_graph->GetName().c_str());
630	
631	  GE_ASSERT_SUCCESS(FusedGraphModifier::SubgraphConnectionsToWorkspace(fused_graph, asc_backend_to_ascgraph),
632	                    "Failed to add workspace between ascgraphs.");
633	  fused_scheduled_result.fused_graph_name = fused_graph->GetName().c_str();
634	
635	  for (auto &node : fused_graph->GetDirectNodePtr()) {
636	    if (node->GetType() == kAscBackendType) {
637	      auto it = asc_backend_to_ascgraph.find(node);
638	      GE_ASSERT_TRUE(it != asc_backend_to_ascgraph.end());
639	      std::vector<::ascir::ScheduledResult> sub_results;
640	      GE_ASSERT_SUCCESS(OptimizeForHintGraph(it->second, sub_results), "optimize failed, graph:[%s].",
641	                        it->second.GetName().c_str());
642	      fused_scheduled_result.node_idx_to_scheduled_results.emplace_back(std::move(sub_results));
643	    }
644	  }
645	  fused_scheduled_result.origin_vars.assign(original_var_set.begin(), original_var_set.end());
646	  BufQueAllocator allocator;
647	  GE_CHK_STATUS_RET(allocator.PrepareImplGraphMemoryPlan(fused_scheduled_result));
648	  GE_CHK_STATUS_RET(StaticUbTemplateFilter().Filter(fused_scheduled_result));
649	  GE_CHK_STATUS_RET(allocator.CollectFusedIoNodes(fused_scheduled_result));
650	  GE_CHK_STATUS_RET(optimize::L2CacheHintManager::ParseGraph(*fused_graph, fused_scheduled_result));
651	  GELOGI("AllocBufQue end");
652	  TryEnableGroupParallel(fused_scheduled_result);
653	  for (auto &scheduled_results : fused_scheduled_result.node_idx_to_scheduled_results) {
654	    for (auto &result : scheduled_results) {
655	      GE_ASSERT_SUCCESS(FusedGraphModifier::ChangeStartingOutputToWorkspace(result.schedule_groups),
656	                        "Change starting output to workspace failed.");
657	    }
658	  }
659	  ascir::utils::DumpScheduleResult(fused_scheduled_result, "AutoFuseAfterOptimize");
660	  return af::SUCCESS;
661	}
