686	Status Optimizer::GetNonContinuousAxisPairBySpecialRule(ascir::ImplGraph &impl_graph,
687	                                                        std::set<std::pair<int64_t, int64_t>> &non_continuous_pair) {
688	  for (const auto &node : impl_graph.GetAllNodes()) {
689	    if (ScheduleUtils::IsConcat(node) || (ScheduleUtils::IsSplit(node))) {
690	      const std::vector<af::Expression> &input_repeats = node->inputs[0].attr.repeats;
691	      const std::vector<af::Expression> &output_repeats = node->outputs[0].attr.repeats;
692	      GE_ASSERT_TRUE((input_repeats.size() == output_repeats.size()),
693	                     "The output dim cnt [%zu] of concat mismatch with input dim cnt [%zu].", output_repeats.size(),
694	                     input_repeats.size());
695	
696	      af::Expression pre_size = af::sym::kSymbolOne;
697	      uint32_t concat_dim{0U};
698	      for (uint32_t i = 0U; i < input_repeats.size(); ++i) {
699	        if (af::SymbolicUtils::StaticCheckEq(input_repeats[i], output_repeats[i]) != af::TriBool::kTrue) {
700	          concat_dim = i;
701	          break;
702	        }
703	        pre_size = pre_size * input_repeats[i];
704	      }
705	
706	      if ((concat_dim > 0U) &&
707	          (af::SymbolicUtils::StaticCheckEq(pre_size, af::sym::kSymbolOne) != af::TriBool::kTrue)) {
708	        non_continuous_pair.emplace(concat_dim - 1, concat_dim);
709	      }
710	      bool no_merge_first_axis = false;
711	      (void)af::AttrUtils::GetBool(node->GetOpDesc(), "_keep_first_axis", no_merge_first_axis);
712	      if (no_merge_first_axis) {
713	        non_continuous_pair.emplace(0, 1);
714	      }
715	    }
716	
717	    if (ScheduleUtils::IsLoad(node)) {
718	      auto strides = node->outputs[0U].attr.strides;
719	      for (int64_t i = static_cast<int64_t>(strides.size() - 1); i >= 0; --i) {
720	        if (af::SymbolicUtils::StaticCheckEq(strides[i], af::sym::kSymbolZero) == af::TriBool::kTrue) {
721	          continue;
722	        }
723	        if (af::SymbolicUtils::StaticCheckEq(strides[i], af::sym::kSymbolOne) == af::TriBool::kTrue) {
724	          break;
725	        } else {
726	          GELOGD("Node [%s] is last axis load, axis:[%ld].", node->GetNamePtr(), i);
727	          non_continuous_pair.emplace(i - 1, i);
728	          break;
729	        }
730	      }
731	      continue;
732	    }
733	
734	    if (ScheduleUtils::IsGather(node)) {
735	      int64_t attr_axis = -1;
736	      ScheduleUtils::GetNodeIrAttrValue(node, "axis", attr_axis);
737	      // scalar == input[0].repeat.size() - 1 --> gather尾轴场景
738	      if (static_cast<size_t>(attr_axis) == node->inputs[0].attr.repeats.size() - 1 && attr_axis != 0) {
739	        non_continuous_pair.emplace(attr_axis - 1, attr_axis);
740	      }
741	      // scalar != input[0].repeat.size() - 1 --> gather非尾轴场景
742	      if (static_cast<size_t>(attr_axis) != node->inputs[0].attr.repeats.size() - 1) {
743	        auto indices = node->inputs[1].attr.repeats;
744	        attr_axis = attr_axis + indices.size() - 1;
745	        non_continuous_pair.emplace(attr_axis, attr_axis + 1);
746	      }
747	    }
748	
749	    if (node->GetType() == "Softmax") {
750	      auto axis_size = static_cast<int64_t>(node->inputs[0].attr.repeats.size());
751	      if (axis_size > 1) {
752	        non_continuous_pair.emplace(
753	            axis_size - 2, axis_size - 1);  // Softmax沿最后一个轴做归约，最后两个轴(axis - 2、axis - 1)不能合并
754	      }
755	    }
756	  }
757	  return af::SUCCESS;
758	}
