760	Status Optimizer::RemoveAllZeroStrideLoopAxis(ascir::ImplGraph &owner_graph) {
761	  if (ScheduleUtils::HasComputeType(owner_graph, af::ComputeType::kComputeGather)) {
762	    return af::SUCCESS;
763	  }
764	  std::unordered_set<size_t> zero_stride_axis_indices = IdentifyZeroStrideAxisIndices(owner_graph);
765	  if (zero_stride_axis_indices.empty()) {
766	    return af::SUCCESS;
767	  }
768	
769	  for (const auto &node : owner_graph.GetAllNodes()) {
770	    GE_ASSERT_NOTNULL(node);
771	    if (ScheduleUtils::IsBuffer(node)) {
772	      continue;
773	    }
774	
775	    std::vector<int64_t> valid_axis_ids;
776	    const auto &original_axis_ids = node->attr.sched.axis;
777	    for (size_t i = 0UL; i < original_axis_ids.size(); ++i) {
778	      if (zero_stride_axis_indices.count(i) == 0UL) {
779	        valid_axis_ids.push_back(original_axis_ids[i]);
780	      }
781	    }
782	    node->attr.sched.axis = valid_axis_ids;
783	
784	    for (const auto &output : node->outputs()) {
785	      std::vector<int64_t> new_axis_ids;
786	      std::vector<af::Expression> new_repeats;
787	      std::vector<af::Expression> new_strides;
788	
789	      for (size_t i = 0UL; i < output->attr.axis.size(); ++i) {
790	        auto axis_id = output->attr.axis[i];
791	        if (std::find(valid_axis_ids.begin(), valid_axis_ids.end(), axis_id) != valid_axis_ids.end()) {
792	          new_axis_ids.push_back(axis_id);
793	          GE_ASSERT_TRUE(i < output->attr.strides.size());
794	          GE_ASSERT_TRUE(i < output->attr.repeats.size());
795	          new_strides.push_back(output->attr.strides[i]);
796	          new_repeats.push_back(output->attr.repeats[i]);
797	        }
798	      }
799	
800	      output->attr.axis = new_axis_ids;
801	      output->attr.strides = new_strides;
802	      output->attr.repeats = new_repeats;
803	    }
804	  }
805	  return af::SUCCESS;
806	}
