808	Status Optimizer::MergeContinuousAxis(ascir::ImplGraph &impl_graph, ascir::CubeTemplateType cube_type) {
809	  auto all_axis = impl_graph.GetAllAxis();
810	  if (all_axis.size() <= 1UL || ascgen_utils::indirect_load::FindIndirectLoadNode(impl_graph) != nullptr) {
811	    return af::SUCCESS;
812	  }
813	  // concat等场景,会有多套轴, 只能先用循环轴的index来生成潜在连续组, 后续根据连续组会找到多个连续轴
814	  std::vector<std::pair<int64_t, int64_t>> potential_axis_idx;
815	  for (const auto &node : impl_graph.GetAllNodes()) {
816	    if (!ScheduleUtils::IsBuffer(node)) {
817	      auto axis_ids = node->attr.sched.axis;
818	      potential_axis_idx.reserve(axis_ids.size() - 1);
819	      for (size_t i = 0UL; i < axis_ids.size() - 1; ++i) {
820	        potential_axis_idx.emplace_back(i, i + 1);
821	      }
822	      break;
823	    }
824	  }
825	
826	  // 剔除根据规则产生的不连续轴(后续reduce和brc考虑放规则里, 减少全局判断耗时
827	  std::set<std::pair<int64_t, int64_t>> non_continuous_pair;
828	  GE_ASSERT_SUCCESS(GetNonContinuousAxisPairBySpecialRule(impl_graph, non_continuous_pair));
829	  potential_axis_idx.erase(
830	      std::remove_if(potential_axis_idx.begin(), potential_axis_idx.end(),
831	                     [&non_continuous_pair](const auto &pair) { return non_continuous_pair.count(pair) > 0; }),
832	      potential_axis_idx.end());
833	
834	  // 剩下的根据全图repeat/stride判断是否连续
835	  for (auto it = potential_axis_idx.rbegin(); it != potential_axis_idx.rend();) {
836	    if (!IsAxisContinuous(impl_graph, it->first, it->second)) {
837	      auto normal_it = it.base();
838	      ++it;
839	      potential_axis_idx.erase(normal_it - 1);
840	    } else {
841	      ++it;
842	    }
843	  }
844	  // 现根据id合并pair
845	  std::vector<std::vector<int64_t>> merged_axis_indexes = MergeContinuousPairs(potential_axis_idx);
846	  std::map<std::vector<af::AxisId>, af::AxisId> from_id_to_merged_id;
847	  std::vector<af::AxisPtr> new_merged_axes;
848	  // Do merge
849	  for (auto node : impl_graph.GetAllNodes()) {
850	    if (ScheduleUtils::IsBuffer(node)) {
851	      continue;
852	    }
853	    std::vector<af::AxisId> node_merged_id;
854	    for (const auto &from_idx : merged_axis_indexes) {
855	      std::vector<af::AxisId> from_ids;
856	      for (const int64_t index : from_idx) {
857	        from_ids.emplace_back(node->attr.sched.axis[index]);
858	      }
859	      auto iter = from_id_to_merged_id.find(from_ids);
860	      if (iter == from_id_to_merged_id.end()) {
861	        auto merged_axis = impl_graph.MergeAxis(from_ids);
862	        new_merged_axes.push_back(merged_axis);
863	        node_merged_id.push_back(merged_axis->id);
864	        from_id_to_merged_id[from_ids] = merged_axis->id;
865	      } else {
866	        node_merged_id.push_back(iter->second);
867	      }
868	    }
869	    for (auto axis_id : node_merged_id) {
870	      GELOGD("Apply merged axis id [%ld] to node:[%s].", axis_id, node->GetNamePtr());
871	      GE_ASSERT_TRUE(impl_graph.ApplyMerge(node, axis_id), "Failed to apply merged axis id %ld to node:[%s].", axis_id,
872	                     node->GetNamePtr());
873	    }
874	  }
875	
876	  // TTODO 需要考虑删轴等操作,后续优化
877	  int64_t attr_axis = -1;
878	  int64_t param_size = -1;
879	  bool has_gather = ScheduleUtils::GetGatherParams(impl_graph, attr_axis, param_size);
880	  if ((!has_gather) && (cube_type != ascir::CubeTemplateType::kUBFuse)) {
881	    // 此处合轴后的轴可以认为是original的
882	    for (const auto &axis : new_merged_axes) {
883	      axis->type = af::Axis::Type::kAxisTypeOriginal;
884	      axis->from.clear();
885	    }
886	    if (cube_type == ascir::CubeTemplateType::kUBFuse) {
887	      return af::GRAPH_SUCCESS;
888	    }
889	    GE_ASSERT_SUCCESS(ScheduleUtils::RemoveUnusedAxes(impl_graph), "Failed to remove unused axes");
890	  }
891	
892	  return af::SUCCESS;
893	}
