895	Status Optimizer::OptimizeForHintGraph(af::AscGraph &hint_graph,
896	                                       std::vector<ascir::ScheduledResult> &scheduled_results) const {
897	  ScheduleUtils::NormalizeAxisIds(hint_graph);
898	  hint_graph.SetGraphType(af::AscGraphType::kImplGraph);
899	  ascir::utils::DumpPyCode(hint_graph);
900	  GE_CHK_STATUS_RET(AscGraphInfoComplete::CompleteApiInfo(hint_graph), "CompleteApiInfo failed");
901	  GE_ASSERT_SUCCESS(CheckGraphValidity(hint_graph), "Check graph validity failed, graph:[%s].",
902	                    hint_graph.GetName().c_str());
903	  // 预处理：当前仅针对kFusedAscBackend流程生效，后续会全部放开
904	  if (options_.graph_type == GraphType::kFusedAscBackend) {
905	    GE_CHK_STATUS_RET(af::pre_process::PreProcess::Run(hint_graph), "Pre process failed");
906	    ascir::utils::DumpGraph(hint_graph, "AfterPreProcess");
907	  }
908	  // 截断 graph name
909	  std::string base_graph_name = TruncateGraphName(hint_graph.GetName());
910	  ascir::ImplGraph optimize_graph(base_graph_name.c_str());
911	  GE_ASSERT_TRUE(optimize_graph.CopyFrom(hint_graph));
912	
913	  // dtype 兜底处理：针对算子实际支持的 dtype 与注册不一致的情况，插入必要的 Cast
914	  GE_CHK_STATUS_RET(DtypeConsistency::EnsureDtypeConsistency(optimize_graph), "Failed to ensure dtype consistency");
915	  ascir::utils::DumpGraph(optimize_graph, "AfterDtypeConsistency");
916	
917	  GE_CHK_STATUS_RET(GraphPass(optimize_graph), "Run graph passes failed");
918	
919	  GE_CHK_STATUS_RET(AscGraphInfoComplete::CompleteApiInfo(optimize_graph), "CompleteApiInfo failed");
920	  GE_ASSERT_GRAPH_SUCCESS(ScheduleUtils::TopologicalSorting(optimize_graph));
921	  utils::DumpGraph(optimize_graph, "AfterGraphPass");
922	  // cube拆分后再做合轴
923	  if (!ScheduleUtils::HasComputeType(optimize_graph, af::ComputeType::kComputeCube)) {
924	    // 这里concat已经打破了一套轴的约束
925	    GE_ASSERT_SUCCESS(RemoveAllZeroStrideLoopAxis(optimize_graph), "Remove All zero stride axis failed.");
926	    GE_ASSERT_SUCCESS(MergeContinuousAxis(optimize_graph), "Merge continuous axes failed.");
927	  }
928	  ascir::utils::DumpGraph(optimize_graph, "AfterMergeAxis");
929	
930	  std::vector<ScheduleTask> schedule_tasks;
931	  GE_CHK_STATUS_RET(ScheduleTaskGenerator::GenerateTasks(optimize_graph, schedule_tasks, options_),
932	                    "Generate tasks failed");
933	  for (size_t i = 0U; i < schedule_tasks.size(); ++i) {
934	    GE_CHK_STATUS_RET(AutoScheduler(hint_graph, schedule_tasks[i], scheduled_results), "AutoScheduler task[%zu] failed",
935	                      i);
936	    GELOGI("AutoScheduler task[%zu] end", i);
937	  }
938	
939	  // 最终处理：添加 SizeVar 和索引后缀
940	  GE_ASSERT_SUCCESS(FinalizeIndexedGraphs(scheduled_results));
941	
942	  return af::SUCCESS;
943	}
