945	/**
946	 * 用于调整load执行顺序，具体步骤如下：
947	 * 1. 获取节点之间的连边关系
948	 * 2. 按序遍历所有节点，从第二个load开始，先判断其是否存在内存共复用，若存在则跳过；
949	 *    若不存在则采用并查集判定其与首load是否具有公共计算节点，若有则前移；若无则不作处理；
950	 *    直到达到最大可调序load个数或遍历结束即退出
951	 * 3. 对load前移后的图进行reorder
952	 * @param impl_graph
953	 * @return
954	 */
955	Status Optimizer::LoadOpSeqAdjust(const af::AscGraph &impl_graph) {
956	  std::map<int64_t, int64_t> need_forward_nodes_id;
957	  int64_t first_load_id = kInvalidNodeId;
958	  GE_ASSERT_SUCCESS(SearchNodesNeedForward(impl_graph, need_forward_nodes_id, first_load_id));
959	  GE_ASSERT_SUCCESS(DoSeqAdjustment(impl_graph, need_forward_nodes_id, first_load_id));
960	  const auto &compute_graph = af::AscGraphUtils::GetComputeGraph(impl_graph);
961	  GE_ASSERT_NOTNULL(compute_graph);
962	  compute_graph->ReorderByNodeId();
963	  return af::SUCCESS;
964	}
