966	Status Optimizer::Optimize(af::AscGraph &hint_graph, FusedScheduledResult &fused_scheduled_result) {
967	  ascir::utils::DumpGraph(hint_graph, "AutoFuseBeforeRemoveDanglingNodes");
968	  GE_CHK_STATUS_RET(RemoveDanglingNodes(hint_graph), "Remove dangling nodes failed, graph:[%s].",
969	                    hint_graph.GetName().c_str());
970	  ascir::utils::DumpGraph(hint_graph, "AutoFuseBeforeOptimize");
971	  fused_scheduled_result.node_idx_to_scheduled_results.resize(1UL);
972	  SizeVarSet original_var_set;
973	  AscGraphInfoComplete::AppendOriginalSizeVar(hint_graph, original_var_set);
974	  GE_ASSERT_SUCCESS(OptimizeForHintGraph(hint_graph, fused_scheduled_result.node_idx_to_scheduled_results[0UL]),
975	                    "Failed to optimize for graph:[%s].", hint_graph.GetName().c_str());
976	  // 内存分配
977	  BufQueAllocator allocator;
978	  GE_CHK_STATUS_RET(allocator.PrepareImplGraphMemoryPlan(fused_scheduled_result));
979	  if (options_.graph_type == GraphType::kAscGraph) {
980	    fused_scheduled_result.fused_graph_name = hint_graph.GetName().c_str();
981	    fused_scheduled_result.origin_vars.assign(original_var_set.begin(), original_var_set.end());
982	  }
983	  GE_CHK_STATUS_RET(StaticUbTemplateFilter().Filter(fused_scheduled_result));
984	  GE_CHK_STATUS_RET(allocator.CollectFusedIoNodes(fused_scheduled_result));
985	  const auto compute_graph = af::AscGraphUtils::GetComputeGraph(hint_graph);
986	  GE_ASSERT_NOTNULL(compute_graph);
987	  GE_CHK_STATUS_RET(optimize::L2CacheHintManager::ParseGraph(*compute_graph, fused_scheduled_result));
988	  GELOGI("AllocBufQue end");
989	  TryEnableGroupParallel(fused_scheduled_result);
990	  ExecSeqAdvancedOfLoad(fused_scheduled_result);
991	  ascir::utils::DumpScheduleResult(fused_scheduled_result, "AutoFuseAfterOptimize");
992	  return af::SUCCESS;
993	}
