1129	void Optimizer::ExecSeqAdvancedOfLoad(const FusedScheduledResult &fused_scheduled_result) {
1130	  for (auto &scheduled_results : fused_scheduled_result.node_idx_to_scheduled_results) {
1131	    for (auto &schedule_result : scheduled_results) {
1132	      if (schedule_result.cube_type == ascir::CubeTemplateType::kUBFuse) {
1133	        continue;
